-- A reading copy of the schema the migrations leave: generated by npm run db:schema, not to be run.

CREATE OR REPLACE FUNCTION public.token_session_open()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (
    select 1 from auth.sessions s
     where s.id = case
                    when auth.jwt() ->> 'session_id'
                         ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
                    then (auth.jwt() ->> 'session_id')::uuid
                  end
       and s.user_id = auth.uid()
       and (s.not_after is null or s.not_after > now()));
$function$;

grant execute on function public.token_session_open() to service_role;
